// 울산여자고등학교 (울산 남구) - automatic high-school package (auto-school track, user decision 2026-10-23). Generated by scripts/campuses/ulsangirls/build-package.mjs
// from OSM way/551772758 + AWS Terrain Tiles: every school building destructible (grammar models, floors estimated where OSM has none),
// a baked ground (one terrain mesh with two drawn colour maps), fence / gates / stands / goals, trees and the extruded neighbourhood fading
// into the haze. Local only (registry public: false). Do not edit by hand - rerun the generator.
import { WORLD_UNITS_PER_METER, GEO_ORIGIN, ULSANGIRLS_PLACEMENTS, ULSANGIRLS_BUILDING_BASE, ULSANGIRLS_HEIGHT_GRIDS, ULSANGIRLS_HEIGHT_RANGE_M, ULSANGIRLS_ENV_IDS, ULSANGIRLS_DISPLAY, ULSANGIRLS_START_FRAME, ULSANGIRLS_OVERVIEW_AZIMUTH, ULSANGIRLS_CAMERA, ULSANGIRLS_PROVENANCE } from './data.js';
import { ULSANGIRLS_FOOTPRINTS } from './footprints.js';
import { ULSANGIRLS_PROTECTED } from './protected.js';

const MODEL_IDS = Object.freeze(ULSANGIRLS_PLACEMENTS.map(p => p.id));
const asset = file => new URL(`../../../assets/campuses/ulsangirls/${file}`, import.meta.url).href;
const HAZE = ULSANGIRLS_DISPLAY.haze, FADE = ULSANGIRLS_DISPLAY.fade;

export const ULSANGIRLS = Object.freeze({
  id: 'ulsangirls',
  meta: Object.freeze({ school: '울산여자고등학교', campus: '울산 남구', short: '울산여고', modelNoun: '울산여고' }),
  geo: Object.freeze({ origin: GEO_ORIGIN, worldUnitsPerMeter: WORLD_UNITS_PER_METER }),
  placements: ULSANGIRLS_PLACEMENTS,
  approvedCount: ULSANGIRLS_PLACEMENTS.length,
  additionalCount: 0,
  coreIds: MODEL_IDS,
  startBuildingId: MODEL_IDS[0],
  // camera picked by scripts/auto-school/build.mjs from the measured occlusion (azimuths in radians, elevations in degrees, src/camera.js angles)
  view: Object.freeze({ get startFrame() { return (globalThis.innerWidth || 1280) < 600 ? { min: [-26,-48,-34], max: [35,10,-4], azimuth: .7, elevationDegrees: 20 } : { min: [-43,0,-39], max: [41,10,0], azimuth: -.3 }; }, overviewAzimuth: -.3 }),
  camera: ULSANGIRLS_CAMERA,
  models: Object.freeze({
    manifests: Object.freeze([
      Object.freeze({ url: asset('manifest.json'), expectedIds: MODEL_IDS }),
      Object.freeze({ url: asset('environment.json'), expectedIds: ULSANGIRLS_ENV_IDS }),
    ]),
    proceduralIds: Object.freeze([]),
    createProceduralSource: () => { throw new Error('No procedural buildings in this campus'); },
    enhanceFacade: () => ({ stats: {}, dispose() {} }),
  }),
  terrain: Object.freeze({ heightGrids: ULSANGIRLS_HEIGHT_GRIDS, buildingBase: ULSANGIRLS_BUILDING_BASE, source: ULSANGIRLS_PROVENANCE.terrain }),
  environment: Object.freeze({ provenance: ULSANGIRLS_PROVENANCE, sourceNote: 'OSM ground surfaces and surroundings (© OpenStreetMap contributors, ODbL); heights, floors and planting estimated automatically' }),
  ground: Object.freeze({
    baked: Object.freeze({ envIds: ULSANGIRLS_ENV_IDS, castShadow: Object.freeze([]),
      fade: Object.freeze({ centre_m: Object.freeze([...FADE.centreEN]), near_m: FADE.r0_m, far_m: FADE.r1_m, linear: FADE.linearShare, colour: HAZE }), playMargin_m: 30,
      source: 'scripts/campuses/ulsangirls/build-package.mjs baked ground' }),
  }),
  protected: Object.freeze({ models: ULSANGIRLS_PROTECTED }),
  hazardTape: Object.freeze({ footprints: ULSANGIRLS_FOOTPRINTS }),
  scene: Object.freeze({
    background: HAZE, fog: Object.freeze({ color: HAZE, near: 500, far: 1400 }),
    hemisphere: Object.freeze({ sky: '#ffffff', ground: '#7d8a78', intensity: 1.35 }),
    sun: Object.freeze({ color: '#fff4e2', intensity: 3.1, position: Object.freeze([-110, 165, 140]), shadowSpan: 200 }),
    floor: Object.freeze({ color: '#c9cbc8', hidden: true, y: ULSANGIRLS_HEIGHT_RANGE_M[0] * WORLD_UNITS_PER_METER - .3 }),
  }),
});
export default ULSANGIRLS;
